import hashlib,json,subprocess,sys
from pathlib import Path
import pdfminer
from pdfminer.high_level import extract_text
base=Path(sys.argv[1]).resolve();request_file=Path(sys.argv[2]).resolve();expected_sha=sys.argv[3];root=Path.cwd()
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
read=lambda p:json.loads(Path(p).read_text())
def need(ok,message):
    if not ok:raise ValueError(message)
def write(p,value):
    with p.open('x') as f:json.dump(value,f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
need(sha(request_file)==expected_sha,'frozen separate-reader request');req=read(request_file)
need(pdfminer.__version__==req['pdfminer_version'] and sha(req['render_binary'])==req['render_binary_sha256'],'bound independent reader/render tools')
paths={}
for key in req['input_sha256']:
    prefix,rel=key.split('/',1);anchor={'repo':root,'source':base}[prefix].resolve();path=(anchor/rel).resolve();need(path.is_relative_to(anchor),'bounded input namespace');paths[key]=path
paths['frozen_request']=request_file;expected={**req['input_sha256'],'frozen_request':expected_sha}
need({k:sha(p) for k,p in paths.items()}==expected,'unchanged independent-reader inputs')
source=base/req['output_subdir'];terminal=read(source/'terminal.json');need(terminal['completed'],'completed original source inspection')
for name,h in terminal['output_sha256'].items():need(sha(source/name)==h,'source-inspection output identity')
source_before={str(p.relative_to(source)):sha(p) for p in sorted(source.rglob('*')) if p.is_file()}
inspection=read(source/'inspection.json');need(len(inspection['documents'])==4,'all four source cases retained')
need(sum(len(d['retained_physical_pages']) for d in inspection['documents'])<=24 and sum(len(d['render_physical_pages']) for d in inspection['documents'])<=12,'bound separate-reader pages')
out=base/req['separate_reader_output_subdir'];out.mkdir(exist_ok=False);write(out/'input-before.json',expected);complete=[];original=None
try:
    docs={d['capture_key']:d for d in req['documents']}
    for row in inspection['documents']:
        doc=docs[row['capture_key']];pdf=base/doc['source_path'];need(sha(pdf)==doc['source_sha256'],'original PDF before independent read');directory=out/doc['capture_key'];directory.mkdir()
        for number in row['retained_physical_pages']:
            text=extract_text(str(pdf),page_numbers=[number-1])
            with (directory/f'pdfminer-page-{number}.txt').open('x') as f:f.write(text)
        for number in row['render_physical_pages']:
            subprocess.run([req['render_binary'],'-f',str(number),'-l',str(number),'-r','110','-singlefile','-png',str(pdf),str(directory/f'original-page-{number}')],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
        complete.append({'capture_key':doc['capture_key'],'independently_extracted_physical_pages':row['retained_physical_pages'],'original_render_physical_pages':row['render_physical_pages']})
except BaseException as exc:original=exc
finally:
    mismatches=[]
    for key,path in paths.items():
        try:
            if sha(path)!=expected[key]:mismatches.append(key)
        except BaseException:mismatches.append(key)
    if sha(req['render_binary'])!=req['render_binary_sha256']:mismatches.append('render_binary')
    if source_before!={str(p.relative_to(source)):sha(p) for p in sorted(source.rglob('*')) if p.is_file()}:mismatches.append('original_inspection_outputs')
    write(out/'terminal.json',{'completed':original is None and not mismatches and len(complete)==4,'documents':complete,'all_inputs_outputs_unchanged':not mismatches,'mismatches':mismatches,
       'request_sha256':expected_sha,'all_input_sha256':expected,'source_inspection_sha256':source_before,'output_sha256':{str(p.relative_to(out)):sha(p) for p in sorted(out.rglob('*')) if p.is_file()},
       'original_error':None if original is None else {'type':type(original).__name__,'message':str(original)},'manual_visual_QA_complete':False,'denominator_admitted':False,'investment_factor_admitted':False})
if original is not None:raise original
need(not mismatches,'reader source/input identities unchanged');print('four independent source cases complete; denominator admission remains false')
